// P12-06 CORRIDOR-REGION PARITY + FLAGSHIP CONGESTED-ROUTE RANKING — end-to-end
// over the ingested CalTrans highwaySegments (highways/ingest.ts) against the
// same-source corridor ground-truth fixture (fixtures/postgis-corridor.json,
// regenerated by scripts/highways_load.mjs).
//
// Talks to the LIVE dev deployment (sensible-oriole-832) via ConvexHttpClient,
// so it exercises the real bbox+haversine LINE path (lib/spatial.segmentsInBbox)
// over the 6,865 ingested segments. SKIPS LOUDLY (throws) — never vacuously
// green — when the deployment is unreachable, the highwaySegments table is empty
// (ingest deferred), or the corridor fixture is absent.
//
// ── HONESTY / SOURCE-MISMATCH NOTE (read before editing an assertion) ─────────
// The docker PostGIS instance has NO CalTrans highwaySegments/AADT table (it
// holds chargers + nhfn_network only), so a literal PostGIS ST_Extent ground
// truth for CalTrans segments does not exist and MUST NOT be fabricated. Per the
// plan's T-12-06d contingency, the parity gate is asserted against the
// SAME-SOURCE ground truth: fixtures/postgis-corridor.json holds the segmentId
// set whose bbox overlaps the POLB→SB corridor bbox, computed INDEPENDENTLY (in
// scripts/highways_load.mjs, plain-JS bbox-intersection over the raw prepped
// rows — the ST_&&-bbox equivalent). The test asserts Convex segmentsInBbox
// returns the IDENTICAL membership. The source note is documented, not papered
// over: this proves the Convex corridor-region query and the reference bbox math
// agree exactly on the same data.
//
// Run: node --import tsx --test convex/highways/queries.test.ts
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { ConvexHttpClient } from "convex/browser";
import { api } from "../_generated/api.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const FIXTURE = resolve(__dirname, "..", "fixtures", "postgis-corridor.json");

interface CorridorFixture {
  source: string;
  note: string;
  bbox: { minLat: number; minLng: number; maxLat: number; maxLng: number };
  segmentIds: string[];
  count: number;
}
interface RegionRow {
  segmentId: string;
  route: string;
  truckAADT: number | null;
  aadt: number | null;
}
interface RouteRank {
  route: string;
  sumTruckAADT: number;
  maxTruckAADT: number;
  segmentCount: number;
}

function convexUrl(): string | null {
  if (process.env.NEXT_PUBLIC_CONVEX_URL) return process.env.NEXT_PUBLIC_CONVEX_URL;
  const envPath = resolve(__dirname, "..", "..", ".env.local");
  if (!existsSync(envPath)) return null;
  const m = readFileSync(envPath, "utf8").match(/^NEXT_PUBLIC_CONVEX_URL=(.+)$/m);
  return m ? m[1].trim() : null;
}

interface Boot {
  bootErr: string | null;
  fixture: CorridorFixture | null;
  corridorRows: RegionRow[];
  topRoutes: RouteRank[];
  fullRanking: RouteRank[];
}

let _bootPromise: Promise<Boot> | null = null;
function boot(): Promise<Boot> {
  if (_bootPromise) return _bootPromise;
  _bootPromise = (async (): Promise<Boot> => {
    const out: Boot = {
      bootErr: null,
      fixture: null,
      corridorRows: [],
      topRoutes: [],
      fullRanking: [],
    };
    if (!existsSync(FIXTURE)) {
      out.bootErr =
        `Corridor fixture absent (${FIXTURE}). Run scripts/highways_load.mjs ` +
        "to regenerate it from the prepped CalTrans rows.";
      return out;
    }
    out.fixture = JSON.parse(readFileSync(FIXTURE, "utf8")) as CorridorFixture;

    const url = convexUrl();
    if (!url) {
      out.bootErr = "NEXT_PUBLIC_CONVEX_URL absent (checked env + apps/web/.env.local)";
      return out;
    }
    try {
      const client = new ConvexHttpClient(url);
      const b = out.fixture.bbox;
      out.corridorRows = (await client.query(api.highways.queries.segmentsInBbox, {
        minLat: b.minLat,
        minLng: b.minLng,
        maxLat: b.maxLat,
        maxLng: b.maxLng,
      })) as RegionRow[];
      out.topRoutes = (await client.query(api.highways.queries.mostCongestedRoute, {
        limit: 1,
      })) as RouteRank[];
      out.fullRanking = (await client.query(api.highways.queries.mostCongestedRoute, {
        limit: 25,
      })) as RouteRank[];
      if (out.corridorRows.length === 0) {
        out.bootErr =
          "Convex highwaySegments returned 0 rows in the corridor bbox — the " +
          "ingest was deferred / the table is empty. Run highways/ingest first.";
      }
    } catch (e) {
      out.bootErr = `Convex deployment unreachable: ${(e as Error).message}`;
    }
    return out;
  })();
  return _bootPromise;
}

function liveTest(name: string, fn: (b: Boot) => void | Promise<void>) {
  test(name, async () => {
    const b = await boot();
    if (b.bootErr) {
      throw new Error(
        `LIVE PARITY UNAVAILABLE — refusing to pass vacuously: ${b.bootErr}. ` +
          "Bring the dev deployment + highways ingest up, then re-run.",
      );
    }
    await fn(b);
  });
}

// ── (1) PARITY — Convex segmentsInBbox == same-source corridor ground truth ────
liveTest(
  "corridor-region parity: Convex segmentsInBbox membership == corridor fixture set",
  (b) => {
    const fixture = b.fixture!;
    const convexIds = new Set(b.corridorRows.map((r) => r.segmentId));
    const truthIds = new Set(fixture.segmentIds);

    // Identical membership (the ST_Extent set-parity gate). Report any drift.
    const missing = [...truthIds].filter((id) => !convexIds.has(id));
    const extra = [...convexIds].filter((id) => !truthIds.has(id));
    assert.equal(
      missing.length,
      0,
      `${missing.length} corridor segmentIds in the fixture are missing from ` +
        `Convex segmentsInBbox (first few: ${missing.slice(0, 5).join(", ")})`,
    );
    assert.equal(
      extra.length,
      0,
      `${extra.length} segmentIds returned by Convex are not in the corridor ` +
        `fixture (first few: ${extra.slice(0, 5).join(", ")})`,
    );
    assert.equal(
      convexIds.size,
      truthIds.size,
      `corridor set size mismatch: Convex ${convexIds.size} vs fixture ${truthIds.size}`,
    );
    assert.ok(
      convexIds.size > 0,
      "corridor set must be non-empty (POLB→SB bbox holds CalTrans segments)",
    );
    console.log(
      `[PARITY] corridor-region set parity OK: ${convexIds.size} segments ` +
        `identical (source: ${fixture.source}).`,
    );
  },
);

// ── (2) RANKING — mostCongestedRoute is a real 5-axle ranking, not a constant ──
liveTest(
  "ranking: mostCongestedRoute is data-driven (top route truckAADT > a lower route)",
  (b) => {
    const ranking = b.fullRanking;
    assert.ok(ranking.length >= 2, `need ≥2 routes to prove ordering, got ${ranking.length}`);

    // Strictly descending by aggregate 5-axle truckAADT — proves an ORDER,
    // not a hardcoded single answer.
    for (let i = 1; i < ranking.length; i++) {
      assert.ok(
        ranking[i - 1].sumTruckAADT >= ranking[i].sumTruckAADT,
        `mostCongestedRoute not ordered desc at ${i}: ` +
          `${ranking[i - 1].route}=${ranking[i - 1].sumTruckAADT} then ` +
          `${ranking[i].route}=${ranking[i].sumTruckAADT}`,
      );
    }
    const top = ranking[0];
    const lower = ranking[ranking.length - 1];
    assert.ok(
      top.sumTruckAADT > lower.sumTruckAADT,
      `top route ${top.route} (${top.sumTruckAADT}) must strictly exceed a ` +
        `lower route ${lower.route} (${lower.sumTruckAADT}) — proves ranking, not a constant`,
    );
    assert.ok(top.maxTruckAADT > 0, "top route must carry a positive 5-axle truckAADT");

    // limit=1 returns exactly the head of the ranking (the flagship answer).
    assert.equal(b.topRoutes.length, 1, "mostCongestedRoute({limit:1}) returns exactly 1");
    assert.equal(
      b.topRoutes[0].route,
      top.route,
      "limit:1 head must equal the full-ranking head",
    );

    // Data-driven finding (documented, not hard-asserted to a stale constant):
    // the flagship HARDCODED POLB→SB; the statewide CalTrans 5-axle ranking puts
    // the I-5 freight spine (RTE 5) first. Both the SoCal freight routes (I-10,
    // I-710, SR-60) rank near the top. Surface it for the 12-08 reconciliation.
    console.log(
      `[FLAGSHIP] mostCongestedRoute (data-driven) top = RTE ${top.route} ` +
        `(sum5axle=${top.sumTruckAADT}, maxSeg=${top.maxTruckAADT}, segs=${top.segmentCount}). ` +
        `Full top-5: ${ranking
          .slice(0, 5)
          .map((r) => `RTE${r.route}:${r.sumTruckAADT}`)
          .join(", ")}. ` +
        "Flagship previously HARDCODED POLB→SB; this is now a real query.",
    );
  },
);

// ── (3) DISTINCTNESS — truckAADT (5-axle) kept distinct from aadt (total) ─────
liveTest(
  "distinctness: corridor rows keep 5-axle truckAADT distinct from total aadt (PITFALLS #7)",
  (b) => {
    const withBoth = b.corridorRows.filter(
      (r) => typeof r.truckAADT === "number" && typeof r.aadt === "number",
    );
    assert.ok(withBoth.length > 0, "expected corridor rows carrying both truckAADT and aadt");
    // The 5-axle subset must never EXCEED the total-truck denominator, and the
    // two must not be trivially identical across the board (which would signal a
    // conflation bug).
    let strictlyLess = 0;
    for (const r of withBoth) {
      assert.ok(
        (r.truckAADT as number) <= (r.aadt as number) + 1e-6,
        `${r.segmentId}: 5-axle truckAADT ${r.truckAADT} exceeds total-truck aadt ${r.aadt} (conflation)`,
      );
      if ((r.truckAADT as number) < (r.aadt as number)) strictlyLess += 1;
    }
    assert.ok(
      strictlyLess > withBoth.length / 2,
      "the 5-axle share should be strictly below total-truck AADT on most segments " +
        `(got ${strictlyLess}/${withBoth.length}) — proves the fields are not conflated`,
    );
  },
);
